import{_ as a,o as r,c as d,a2 as o}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"跨位面探索纪元","description":"","frontmatter":{},"headers":[],"relativePath":"zh/78-跨位面探索纪元.md","filePath":"zh/78-跨位面探索纪元.md","lastUpdated":1789183869000}'),l={name:"zh/78-跨位面探索纪元.md"};function e(i,t,n,h,s,u){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="跨位面探索纪元" tabindex="-1">跨位面探索纪元 <a class="header-anchor" href="#跨位面探索纪元" aria-label="Permalink to &quot;跨位面探索纪元&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>78</td></tr><tr><td>所属模块</td><td>历史纪元与重大事件</td></tr><tr><td>核心关键词</td><td>跨位面探索、位面大发现、考古协议、先观测后干涉、星际共生</td></tr></tbody></table><h2 id="一、跨位面探索纪元的开启条件" tabindex="-1">一、跨位面探索纪元的开启条件 <a class="header-anchor" href="#一、跨位面探索纪元的开启条件" aria-label="Permalink to &quot;一、跨位面探索纪元的开启条件&quot;">​</a></h2><p>跨位面探索纪元是万族共和成立后开启的新纪元，对应四阶段升维路径中从&quot;意识进化&quot;向&quot;星际共生&quot;过渡的阶段。这一纪元的开启需要三个条件的同时成熟：</p><ul><li><strong>技术条件</strong>：空间法理技术达到&quot;源空&quot;境界，跨位面通道的稳定开启成为可能；复制镜与隔离空间技术成熟，为低污染探索提供了技术保障</li><li><strong>制度条件</strong>：万族共和成立，统一的跨位面探索政策与考古协议制定完成</li><li><strong>动力条件</strong>：已知位面的升维工作有序推进，文明有能力也有意愿向未知位面扩展</li></ul><p>当这三个条件同时成熟时，万族共和正式宣布启动&quot;大探索计划&quot;，跨位面探索纪元由此开启。</p><h2 id="二、跨位面探索的基本原则" tabindex="-1">二、跨位面探索的基本原则 <a class="header-anchor" href="#二、跨位面探索的基本原则" aria-label="Permalink to &quot;二、跨位面探索的基本原则&quot;">​</a></h2><p>跨位面探索严格遵循以下基本原则，这些原则被写入《跨位面探索基本法》：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>先观测后有限干涉</td><td>对未知位面首先进行被动观测，在充分了解后再进行有限度的接触与干涉</td></tr><tr><td>低污染探索</td><td>采用复制镜+隔离空间的考古方案，仅回传知识，不将物质与生命带入带出</td></tr><tr><td>原生文明保护</td><td>对存在原生文明的位面，尊重其自主发展权，不得强行灌输共生制度</td></tr><tr><td>资源共享</td><td>探索发现的知识与资源归全文明共享，任何组织不得垄断探索成果</td></tr><tr><td>安全优先</td><td>探索过程中的安全始终放在首位，高危位面的探索必须经过严格的风险评估</td></tr></tbody></table><h2 id="三、探索的技术手段" tabindex="-1">三、探索的技术手段 <a class="header-anchor" href="#三、探索的技术手段" aria-label="Permalink to &quot;三、探索的技术手段&quot;">​</a></h2><p>跨位面探索综合运用了共生文明的多项核心技术：</p><ol><li><strong>位面扫描技术</strong>：基于空间法理感知模块的远程位面扫描，可在不接触目标位面的情况下获取其基本信息（空间结构、能量水平、生命迹象等）</li><li><strong>复制镜考古方案</strong>：对目标位面进行高精度镜像复制，在隔离空间中对镜像副本进行深入研究，仅将知识回传</li><li><strong>跨位面通讯探针</strong>：微型法则通讯装置，可送入目标位面进行近距离观测，数据通过跨位面通讯网络实时回传</li><li><strong>意识域感知</strong>：高阶修炼者通过意识域对目标位面进行远程感知，获取扫描技术无法捕捉的意识层面信息</li><li><strong>锚点远程部署</strong>：对安全等级较高的位面，可远程部署临时锚点，建立稳定的连接通道</li></ol><h2 id="四、探索的组织与实施" tabindex="-1">四、探索的组织与实施 <a class="header-anchor" href="#四、探索的组织与实施" aria-label="Permalink to &quot;四、探索的组织与实施&quot;">​</a></h2><p>跨位面探索由万族共和的&quot;跨位面探索局&quot;统一组织实施，采用&quot;分级探索&quot;的模式：</p><table tabindex="0"><thead><tr><th>探索等级</th><th>目标类型</th><th>探索方式</th><th>人员配置</th></tr></thead><tbody><tr><td>一级探索</td><td>无生命的荒芜位面</td><td>远程扫描+复制镜研究</td><td>技术团队为主</td></tr><tr><td>二级探索</td><td>有低等生命的位面</td><td>复制镜考古+有限实地考察</td><td>技术团队+生物学家</td></tr><tr><td>三级探索</td><td>有原生文明的位面</td><td>先观测后接触，严格遵守接触协议</td><td>完整团队+外交官+伦理观察员</td></tr><tr><td>四级探索</td><td>高危/未知位面</td><td>仅限隔离空间模拟研究，禁止实地接触</td><td>最高级别安全团队</td></tr></tbody></table><p>每个探索项目都必须经过&quot;探索申请—风险评估—伦理审查—批准实施—过程监控—成果共享&quot;的完整流程。</p><h2 id="五、探索纪元的重大发现" tabindex="-1">五、探索纪元的重大发现 <a class="header-anchor" href="#五、探索纪元的重大发现" aria-label="Permalink to &quot;五、探索纪元的重大发现&quot;">​</a></h2><p>跨位面探索纪元开启后，共生文明取得了一系列重大发现：</p><ul><li><strong>新种族发现</strong>：在未知位面中发现了大量此前未知的智慧种族，万族谱系大幅扩展。这些新种族经过自愿选择后逐步加入万族共和</li><li><strong>新法则发现</strong>：不同位面的法则结构存在差异，探索中发现了多种新的法则变体，丰富了三百套修炼体系的理论基础</li><li><strong>古文明遗迹</strong>：发现了多个前锚点时代灭绝文明的遗迹，通过复制镜考古获取了大量珍贵的历史知识</li><li><strong>异位面共生文明</strong>：在某些位面发现了独立发展出共生理念的原生文明，与锚点共生文明形成了跨越空间的思想共鸣</li><li><strong>宇宙边界探索</strong>：探索逐步触及衡元宙的已知边界，对宇宙整体结构的认知不断深化</li></ul><h2 id="六、探索中的挑战与反思" tabindex="-1">六、探索中的挑战与反思 <a class="header-anchor" href="#六、探索中的挑战与反思" aria-label="Permalink to &quot;六、探索中的挑战与反思&quot;">​</a></h2><p>跨位面探索并非一帆风顺，过程中也遇到了挑战：</p><ul><li><strong>文化冲突</strong>：与原生文明的接触中出现了文化误解与冲突，促使接触协议不断完善</li><li><strong>探索伦理争议</strong>：对于&quot;是否应当主动接触原生文明&quot;存在持续的伦理辩论，最终形成了&quot;不主动、不回避、尊重选择&quot;的共识</li><li><strong>安全事故</strong>：在高危位面探索中发生过隔离空间屏障破损事故，虽然未造成严重后果，但推动了安全标准的进一步提升</li><li><strong>资源分配</strong>：大规模探索需要消耗大量资源，探索投入与本土民生投入之间的平衡成为政治辩论的焦点</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>跨位面探索纪元是锚点共生文明的&quot;大航海时代&quot;。它将文明的视野从已知位面扩展到了整个宇宙，在发现新世界的同时也深化了对自身的理解。复制镜+隔离空间的低污染探索方案，使得共生文明的探索区别于历史上一切掠夺式的殖民扩张——我们带去的不是征服与掠夺，而是尊重与知识；我们带回的不是资源与奴隶，而是理解与智慧。当探索的位面足够多、锚点网络足够密时，星际共生时代的大门就将缓缓开启。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>77-万族共和成立</li><li>79-星际共生时代展望</li><li>84-考古协议总纲</li></ul>',26)])])}const b=a(l,[["render",e]]);export{g as __pageData,b as default};
